INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (220, 1, 'Never 와 정상 종료', '`restartPolicy: Never` 인 파드의 컨테이너가 종료 코드 `0` 으로 끝나면 `kubectl get pod` 에는 어떻게 보일까요?', '정상 종료는 Completed 예요.', NULL, NULL, '[]', 'choice', '["STATUS 는 `Running` 으로 남고 컨테이너는 같은 파드 안에서 다시 시작되며 RESTARTS 가 `1` 로 늘어난다", "STATUS 는 `Error` 가 되고 파드 단계는 `Failed` 로 표시된다", "STATUS 는 `Completed`, RESTARTS 는 `0` 이고 파드 단계는 `Succeeded` 가 된다", "파드가 스스로 삭제되어 `kubectl get pod` 에 아무것도 보이지 않게 된다"]', 2, '단계(phase)는 `kubectl get pod -o jsonpath=''{.status.phase}''` 로 읽을 수 있습니다.', NULL, NULL, NULL, NULL),
  (220, 2, 'Never 와 실패 종료', '`restartPolicy: Never` 인 파드의 컨테이너가 종료 코드 `1` 로 끝나면 어떻게 될까요?', '다시 시작하지 않는다는 뜻이에요.', NULL, NULL, '[]', 'choice', '["컨테이너가 계속 다시 시작되어 RESTARTS 가 늘어나고 STATUS 는 `CrashLoopBackOff` 가 된다", "다시 시작하지 않고 STATUS 는 `Error`, RESTARTS 는 `0`, 파드 단계는 `Failed` 가 된다", "STATUS 는 `Completed` 가 되고 종료 코드는 `0` 으로 바뀌어 기록된다", "파드가 `Pending` 으로 돌아가 다른 노드에 새로 스케줄된다"]', 1, '종료 코드는 `.status.containerStatuses[0].state.terminated.exitCode` 에 남습니다.', NULL, NULL, NULL, NULL),
  (220, 3, 'OnFailure 와 정상 종료', '`restartPolicy: OnFailure` 인 파드의 컨테이너가 종료 코드 `0` 으로 끝나면 어떻게 될까요?', 'OnFailure 는 실패했을 때만 다시 시작해요.', NULL, NULL, '[]', 'choice', '["다시 시작하지 않고 STATUS 는 `Completed`, RESTARTS 는 `0` 이 된다", "정상 종료여도 다시 시작해서 RESTARTS 가 계속 늘어나게 된다", "종료 코드가 `0` 이어도 실패로 간주해서 STATUS 가 `Error` 가 되고 파드 단계는 `Failed` 가 된다", "STATUS 가 `CrashLoopBackOff` 로 바뀌고 몇 번 쉬었다가 다시 시작한다"]', 0, '`OnFailure` 는 종료 코드가 `0` 이 아닐 때만 같은 파드 안에서 컨테이너를 다시 시작합니다.', NULL, NULL, NULL, NULL),
  (220, 4, 'OnFailure 와 실패 종료', '`restartPolicy: OnFailure` 인 파드의 컨테이너가 종료 코드 `1` 로 계속 끝나면 어떻게 될까요?', '다시 시작하는데 간격이 점점 길어져요.', NULL, NULL, '[]', 'choice', '["다시 시작하지 않고 STATUS 는 `Error`, RESTARTS 는 `0` 으로 한 번만 실행된다", "실패할 때마다 새 파드가 만들어져서 파드 이름이 계속 늘어난다", "세 번 다시 시작한 뒤에는 파드가 스스로 삭제되고 `kubectl get pod` 목록에서 사라져 버린다", "같은 파드 안에서 다시 시작되어 RESTARTS 가 늘고, 곧 STATUS 가 `CrashLoopBackOff` 가 된다"]', 3, '이때 파드 단계는 `Running` 으로 남아 있고, 재시작 사이의 간격은 점점 길어집니다.', NULL, NULL, NULL, NULL),
  (220, 5, 'Always 는 정상 종료도 재시작', '`restartPolicy: Always` (기본값) 인 파드의 컨테이너가 종료 코드 `0` 으로 끝나면 어떻게 될까요?', 'Always 는 항상이라는 뜻이에요.', NULL, NULL, '[]', 'choice', '["정상 종료이므로 STATUS 가 `Completed` 로 남고 RESTARTS 는 `0` 이다", "정상 종료이므로 파드가 삭제되고 같은 이름의 새 파드가 생긴다", "정상 종료여도 컨테이너가 다시 시작되어 RESTARTS 가 계속 늘어난다", "첫 정상 종료 뒤에는 다시 시작하지 않고 실패했을 때만 다시 시작한다"]', 2, '한 번 실행하고 끝나는 작업에는 `Always` 가 맞지 않아서 `Never` 나 `OnFailure` 를 씁니다.', NULL, NULL, NULL, NULL),
  (220, 6, 'Deployment 의 restartPolicy', 'Deployment 의 파드 템플릿에 `restartPolicy: Never` 를 넣고 `kubectl apply` 하면 어떻게 될까요?', 'Deployment 는 파드를 계속 유지해요.', NULL, NULL, '[]', 'choice', '["문제 없이 만들어지고 파드가 한 번 실행된 뒤에는 다시 만들지 않는다", "`Unsupported value: \\"Never\\"` 오류로 거부되고, 가능한 값은 `Always` 뿐이라고 알려 준다", "만들어지지만 경고만 나오고 `Never` 는 `OnFailure` 로 자동으로 바뀌어 파드에 적용된다", "만들어지지만 `kubectl get pod` 에서 파드가 `Pending` 으로 남아 있게 된다"]', 1, 'Deployment 는 `Always` 만 쓸 수 있고, `Never` 와 `OnFailure` 는 Job 의 파드 템플릿에 씁니다.', NULL, NULL, NULL, NULL),
  (220, 7, 'restartPolicy 와 종료 유예 기본값', '`kubectl run g1 --image=busybox:1.36 --command -- sleep 3600` 으로 만든 파드의 `restartPolicy` 와 `terminationGracePeriodSeconds` 는 각각 무엇일까요?', '아무것도 정하지 않은 기본값이에요.', NULL, NULL, '[]', 'choice', '["`Always` 와 `30`", "`Never` 와 `30` 이고 `kubectl run` 으로 만든 파드는 다시 시작하지 않는다", "`Always` 와 `10` 이고 종료 신호를 보낸 뒤 10초 뒤에 강제로 끝낸다", "`OnFailure` 와 `0` 이고 종료 신호 없이 바로 강제로 끝낸다"]', 0, '`kubectl get pod g1 -o jsonpath=''{.spec.terminationGracePeriodSeconds} {.spec.restartPolicy}''` 로 확인할 수 있습니다.', NULL, NULL, NULL, NULL),
  (220, 8, '실행 중 파드의 restartPolicy 바꾸기', '실행 중인 파드에 `kubectl patch pod g1 -p ''{"spec":{"restartPolicy":"Never"}}''` 를 하면 어떻게 될까요?', '파드 스펙은 거의 못 바꿔요.', NULL, NULL, '[]', 'choice', '["바로 적용되어 컨테이너는 다음에 종료될 때부터 새 정책에 따라 다시 시작하지 않게 된다", "적용되지만 컨테이너가 재시작되어야 새 값이 효과를 내게 된다", "적용되고 파드는 `Never` 값에 맞게 같은 이름의 새 파드로 자동으로 교체되어 다시 실행된다", "`Forbidden: pod updates may not change fields other than ...` 오류로 거부된다"]', 3, '바꿀 수 있는 필드는 이미지, `activeDeadlineSeconds`, 톨러레이션 추가, 종료 유예 시간 정도입니다. 나머지는 파드를 새로 만들어야 합니다.', NULL, NULL, NULL, NULL),
  (220, 9, 'kubectl run --restart', '`kubectl run r1 --image=busybox:1.36 --restart=Never --command -- sleep 3600` 은 무엇을 만들까요?', 'run 은 파드를 만들어요.', NULL, NULL, '[]', 'choice', '["`restartPolicy: Never` 인 파드를 감싸는 Job 을 함께 만들어서 파드를 관리하게 해 준다", "`restartPolicy: Never` 를 무시하고 Deployment 를 만들어 준다", "Deployment 나 Job 없이 `restartPolicy: Never` 인 파드 하나만 만든다", "파드 대신 `restartPolicy` 를 정하는 별도의 설정 오브젝트를 만든다"]', 2, '`--restart=OnFailure` 도 Job 이 아니라 `restartPolicy: OnFailure` 인 파드 하나만 만듭니다.', NULL, NULL, NULL, NULL),
  (220, 10, 'Job 의 Never 와 새 파드', '`restartPolicy: Never`, `backoffLimit: 1` 인 Job 의 컨테이너가 계속 실패하면 파드는 몇 개 만들어질까요?', 'Never 는 같은 파드를 다시 쓰지 않아요.', NULL, NULL, '[]', 'choice', '["파드 하나가 만들어지고 그 안에서 컨테이너가 두 번 다시 시작된다", "처음 파드와 재시도 파드까지 두 개가 만들어지고 둘 다 `Error` 로 남는다", "파드 하나만 만들어지고 `backoffLimit` 은 무시된다", "파드가 계속 새로 만들어져서 `backoffLimit` 과 관계없이 끝나지 않는다"]', 1, '`OnFailure` 였다면 같은 파드 안에서 컨테이너를 다시 시작하는 방식으로 재시도합니다.', NULL, NULL, NULL, NULL),
  (220, 11, '종료 코드 읽기', '`sh -c ''exit 3''` 을 실행하는 `restartPolicy: Never` 파드에서 종료 코드는 어디서 읽을까요?', 'containerStatuses 아래를 보세요.', NULL, NULL, '[]', 'choice', '["`.status.containerStatuses[0].state.terminated.exitCode` 에 `3` 으로 남고 파드 단계는 `Failed` 이다", "`.spec.containers[0].exitCode` 에 `3` 으로 남고 파드 단계는 `Succeeded` 이다", "`.metadata.annotations` 에 `3` 으로 남고 파드 단계는 `Failed` 이다", "종료 코드는 기록되지 않고 STATUS 에 `Error` 라는 글자만 표시된다"]', 0, '`reason` 도 같은 위치에 있고 `0` 이 아닌 종료는 `Error` 로 표시됩니다.', NULL, NULL, NULL, NULL),
  (220, 12, 'logs --previous', '컨테이너가 재시작된 뒤 `kubectl logs 파드` 와 `kubectl logs 파드 --previous` 는 각각 무엇을 보여 줄까요?', 'previous 는 직전 컨테이너예요.', NULL, NULL, '[]', 'choice', '["앞은 재시작 직전에 끝난 컨테이너의 로그이고, 뒤는 지금 실행 중인 컨테이너의 로그이다", "앞은 현재 로그 전체이고, 뒤는 이전 로그만 골라서 시간순으로 이어 붙여 보여 주는 옵션이다", "둘 다 지금 실행 중인 컨테이너의 로그이고 `--previous` 는 마지막 10줄만 보여 준다", "앞은 지금 실행 중인 컨테이너의 로그이고, 뒤는 재시작 직전에 끝난 컨테이너의 로그이다"]', 3, '재시작이 한 번도 없으면 `--previous` 는 이전 컨테이너가 없다는 오류를 냅니다.', NULL, NULL, NULL, NULL),
  (220, 13, 'SIGTERM 과 유예 시간', '종료 신호(SIGTERM)를 처리하지 않는 프로세스가 PID 1 인 파드를 삭제하면 언제 끝날까요? 유예 시간은 5초라고 합시다.', '신호를 무시하면 기다리게 돼요.', NULL, NULL, '[]', 'choice', '["신호를 무시해도 즉시 강제로 종료되어 삭제는 항상 1초 안에 끝난다", "신호를 처리하지 않으면 삭제가 끝나지 않고 계속 `Terminating` 으로 남는다", "신호를 무시하므로 5초를 다 기다린 뒤 강제로 종료된다. 신호를 처리해 바로 끝나는 파드는 1초 안에 사라진다", "신호를 처리해야 5초를 기다리고, 처리하지 않으면 바로 강제로 종료된다"]', 2, '`sh -c ''sleep 3600''` 은 PID 1 이 `sh` 라서 TERM 에 반응하지 않고, `trap ''exit 0'' TERM` 을 두면 바로 끝납니다.', NULL, NULL, NULL, NULL),
  (220, 14, '이미지를 못 받는 파드', '받을 수 없는 이미지 `nonexistent.invalid/x:1` 로 만든 파드를 조금 뒤 `kubectl get pod` 로 보면 어떻게 보일까요?', '컨테이너가 시작조차 못 해요.', NULL, NULL, '[]', 'choice', '["STATUS 는 `CrashLoopBackOff` 이고 컨테이너가 시작과 종료를 반복해서 RESTARTS 가 계속 늘어난다", "STATUS 는 `ImagePullBackOff` 이고 컨테이너가 한 번도 시작되지 않아 RESTARTS 는 `0` 이다", "STATUS 는 `Completed` 이고 이미지를 받지 못한 오류는 이벤트에도 기록되지 않는다", "STATUS 는 `Running` 이고 이미지가 없어도 빈 컨테이너가 대신 시작되어 계속 실행된다"]', 1, '원인은 `kubectl describe pod` 의 Events 에서 `Failed to pull image` 로 확인합니다.', NULL, NULL, NULL, NULL),
  (220, 15, '재시작 정책 필드', '파드가 종료된 뒤 **다시 시작할지 정하는** `spec` 필드 이름을 채우세요.', '"재시작"과 "정책"을 이어 써요.', NULL, NULL, '[]', 'fill', '["restartMode", "retryPolicy", "onFailure", "restartPolicy"]', NULL, '값은 `Always`, `OnFailure`, `Never` 세 가지입니다.', '[3]', '{0}: OnFailure', NULL, NULL),
  (220, 16, '다시 시작하지 않는 값', '컨테이너가 종료되면 **어떤 경우에도 다시 시작하지 않는** `restartPolicy` 값을 채우세요.', '"절대 아님"을 영어로 써요.', NULL, NULL, '[]', 'fill', '["Never", "None", "Stop", "Once"]', NULL, 'Job 의 파드 템플릿에는 `Never` 나 `OnFailure` 를 씁니다.', '[0]', 'restartPolicy: {0}', NULL, NULL),
  (220, 17, '기본 재시작 정책', '`restartPolicy` 를 적지 않았을 때 **쓰이는 기본값** 을 채우세요.', '"항상"을 영어로 써요.', NULL, NULL, '[]', 'fill', '["Never", "Always", "OnFailure", "Default"]', NULL, 'Deployment 는 이 값만 쓸 수 있습니다.', '[1]', 'restartPolicy: {0}', NULL, NULL),
  (220, 18, '실패했을 때만 재시작', '컨테이너가 **실패한 경우에만 다시 시작하는** `restartPolicy` 값을 채우세요.', '"실패 시"를 영어로 이어 써요.', NULL, NULL, '[]', 'fill', '["OnError", "IfFailed", "OnFailure", "Retry"]', NULL, '종료 코드가 `0` 이면 다시 시작하지 않습니다.', '[2]', 'restartPolicy: {0}', NULL, NULL),
  (220, 19, '직전 컨테이너 로그', '`kubectl logs` 에서 **재시작되기 직전 컨테이너의 로그를 보는** 옵션을 채우세요.', '"이전의"를 영어로 써요.', NULL, NULL, '[]', 'fill', '["before", "last", "old", "previous"]', NULL, 'CrashLoopBackOff 의 원인을 볼 때 자주 씁니다.', '[3]', 'kubectl logs mypod --{0}', NULL, NULL),
  (220, 20, 'run 의 재시작 옵션', '`kubectl run` 에서 **파드의 재시작 정책을 정하는** 옵션 이름을 채우세요.', '"재시작"을 영어로 써요.', NULL, NULL, '[]', 'fill', '["restart", "policy", "retry", "mode"]', NULL, '`Never` 를 주면 Deployment 없이 파드만 만들어집니다.', '[0]', 'kubectl run r1 --image=busybox --{0}=Never', NULL, NULL),
  (220, 21, '파드 단계 읽기', '`custom-columns` 로 **파드의 단계(Running, Succeeded, Failed)를 읽는** 필드를 채우세요.', '"단계"를 영어로 써요.', NULL, NULL, '[]', 'fill', '["state", "phase", "result", "stage"]', NULL, '정상 종료한 파드는 `Succeeded`, 실패한 파드는 `Failed` 입니다.', '[1]', 'kubectl get pod n1 -o custom-columns=P:.status.{0}', NULL, NULL),
  (220, 22, '종료 유예 시간 필드', '파드가 **종료 신호를 받은 뒤 강제로 끝나기까지 기다리는 시간** 필드의 빠진 부분을 채우세요.', '단위를 영어로 써요.', NULL, NULL, '[]', 'fill', '["Time", "Limit", "Seconds", "Sec"]', NULL, '기본값은 `30` 입니다.', '[2]', 'terminationGracePeriod{0}: 30', NULL, NULL),
  (220, 23, 'Job 재시도 횟수', 'Job 에서 **실패했을 때 재시도하는 횟수의 한도를 정하는** `spec` 필드를 채우세요.', '"뒤로 물러남의 한계"예요.', NULL, NULL, '[]', 'fill', '["retries", "maxRetry", "restartLimit", "backoffLimit"]', NULL, '한도를 넘으면 Job 이 실패로 끝납니다.', '[3]', '{0}: 1', NULL, NULL),
  (220, 24, '이미지를 받지 못할 때', '이미지를 받지 못해 **다음 시도를 기다리는** 파드의 `STATUS` 를 채우세요.', '이미지 받기 실패 후 물러남이에요.', NULL, NULL, '[]', 'fill', '["ImagePullBackOff", "CrashLoopBackOff", "ContainerCreating", "Terminating"]', NULL, '이때 컨테이너는 아직 한 번도 시작되지 않아 RESTARTS 는 `0` 입니다.', '[0]', '0/1   {0}   0', NULL, NULL),
  (220, 25, '명령 덮어쓰기', '`kubectl run` 에서 **이미지의 기본 명령 대신 뒤에 적은 명령을 실행하게 하는** 옵션을 채우세요.', '"명령"을 영어로 써요.', NULL, NULL, '[]', 'fill', '["cmd", "command", "exec", "run"]', NULL, '`--` 뒤에 실행할 명령을 씁니다.', '[1]', 'kubectl run c1 --image=busybox --{0} -- sleep 3600', NULL, NULL),
  (220, 26, 'Never 실패 확인', '`Never` 파드의 실패를 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 목록 → 단계 → 종료 코드 순서예요.', NULL, NULL, '[]', 'order', '["`...terminated.exitCode` 를 읽어 `1` 이 나오는지 확인한다", "`-o jsonpath=''{.status.phase}''` 로 `Failed` 가 나오는지 확인한다", "`restartPolicy: Never` 에 `exit 1` 을 실행하는 파드를 만든다", "`kubectl get pod` 로 STATUS 가 `Error`, RESTARTS 가 `0` 인지 확인한다"]', NULL, '`exit 0` 이었다면 `Completed` 와 `Succeeded` 가 나옵니다.', '[2, 3, 1, 0]', NULL, NULL, NULL),
  (220, 27, 'OnFailure 재시작 관찰', '`OnFailure` 파드가 반복 실패하는 모습을 보는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 재시작 수 → 상태 → 이전 로그 순서예요.', NULL, NULL, '[]', 'order', '["STATUS 가 `CrashLoopBackOff` 로 바뀌는지 확인한다", "`kubectl logs 파드 --previous` 로 직전 컨테이너의 출력을 읽는다", "`kubectl get pod` 로 RESTARTS 가 `1`, `2` 로 늘어나는지 확인한다", "`restartPolicy: OnFailure` 에 `exit 1` 을 실행하는 파드를 만든다"]', NULL, '재시작 간격이 점점 길어져서 STATUS 는 `Error` 와 `CrashLoopBackOff` 사이를 오갑니다.', '[3, 2, 0, 1]', NULL, NULL, NULL),
  (220, 28, 'Job 재시도 확인', '`Never` Job 이 재시도하는 모습을 보는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 파드 수 → 상태 → 정리 순서예요.', NULL, NULL, '[]', 'order', '["두 파드의 STATUS 가 모두 `Error` 인지 확인한다", "`restartPolicy: Never`, `backoffLimit: 1` 에 `exit 1` 을 실행하는 Job 을 만든다", "`kubectl get job` 에서 Job 이 `Failed` 인지 확인한다", "`kubectl get pods -l job-name=이름` 으로 파드가 두 개인지 확인한다"]', NULL, '`OnFailure` 였다면 파드 수는 늘지 않고 RESTARTS 만 늘어납니다.', '[1, 3, 0, 2]', NULL, NULL, NULL),
  (220, 29, '종료 신호 처리 비교', '신호 처리에 따라 삭제 시간이 다른 것을 비교하는 순서입니다. 순서에 맞게 놓아 보세요.', '유예 5초 → 느린 파드 → 빠른 파드 순서예요.', NULL, NULL, '[]', 'order', '["`sh -c ''sleep 3600''` 파드를 삭제하고 약 5초 걸리는지 확인한다", "두 파드의 삭제 시간 차이가 신호 처리 여부에서 온다는 것을 확인한다", "`terminationGracePeriodSeconds: 5` 로 두 파드를 만든다", "`trap ''exit 0'' TERM` 으로 신호를 처리하는 파드를 삭제하고 약 1초 걸리는지 확인한다"]', NULL, '신호를 처리하지 않으면 유예 시간이 다 지난 뒤 강제로 종료됩니다.', '[2, 0, 3, 1]', NULL, NULL, NULL);
